// Exact clean-TEST schema/guard cohort, reusing native invoice and inbound tables.
import fs from 'node:fs';
import {moduleHash} from './stage4-copy-sql.mjs';
import {CLEAN_TARGET_SQL} from './clean-synthetic-sql.mjs';
import {CLEAN_LOGIN} from '../../apps/api/src/services/cleanSyntheticContext.mjs';
import {buildCleanOrderSaleProcedures,buildCleanCompatibleSaleBegin,cleanOrderSaleReadinessSql} from './clean-order-sale-sql.mjs';
import {cleanInboundGuardUpgradePlan,cleanInboundEffectiveDefinitionHashSql} from './clean-store-day-sql.mjs';
const quote=s=>"N'"+s.replaceAll("'","''")+"'";
const deny="THROW 51961,'CLEAN_INBOUND_WRITE_DENIED',1;";
const original=`IF ORIGINAL_LOGIN() COLLATE Latin1_General_100_BIN2<>N'${CLEAN_LOGIN}' ${deny}`;
const active=`EXEC dbo.usp_clean_store_day_ready;
 ${original}
 IF (SELECT COUNT(*) FROM dbo.clean_store_day_intents WHERE session_id=@@SPID AND transaction_id=CURRENT_TRANSACTION_ID())<>1 ${deny}`;
const witness=field=>`SELECT CONVERT(bit,1) ${field},CONVERT(varchar(36),environment_id) environmentId,LOWER(CONVERT(varchar(36),@request_id)) requestId,@actor actorId,@op operation,LOWER(@hash) payloadHash FROM dbo.clean_test_environment WHERE id=1;`;
const I=k=>`ISNULL(JSON_VALUE(@inserted,'$[0].${k}'),N'')`;
const N=k=>`COALESCE(TRY_CONVERT(decimal(28,8),JSON_VALUE(@inserted,'$[0].${k}')),-999999)`;
const unchanged=allowed=>`IF EXISTS(SELECT 1 FROM OPENJSON(JSON_QUERY(@inserted,'$[0]')) i FULL JOIN OPENJSON(JSON_QUERY(@deleted,'$[0]')) d ON i.[key]=d.[key] WHERE COALESCE(i.[key],d.[key]) NOT IN(${allowed.map(quote).join(',')}) AND(i.[key] IS NULL OR d.[key] IS NULL OR i.[type]<>d.[type] OR ISNULL(i.value,N'') COLLATE Latin1_General_100_BIN2<>ISNULL(d.value,N'') COLLATE Latin1_General_100_BIN2)) ${deny}`;
const commonVars=`DECLARE @actor bigint,@op nvarchar(40),@hash char(64),@payload nvarchar(max),@count bigint,@receipt bigint,@invoice bigint,@qty decimal(18,3),@total decimal(18,4),@stock decimal(18,3),@balance decimal(18,4),@receiptBefore nvarchar(20),@invoiceBefore nvarchar(20);
 SELECT @actor=actor_id,@op=operation,@hash=payload_hash,@payload=payload_json,@count=count_id,@receipt=receipt_id,@invoice=invoice_id,@qty=quantity,@total=total,@stock=stock_before,@balance=supplier_balance_before,@receiptBefore=receipt_state_before,@invoiceBefore=invoice_state_before FROM dbo.clean_store_day_intents WHERE session_id=@@SPID AND transaction_id=CURRENT_TRANSACTION_ID();`;
const stockSchema=`IF COL_LENGTH(N'dbo.stock_movements',N'source_warehouse') IS NULL ALTER TABLE dbo.stock_movements ADD source_warehouse nvarchar(100) NULL;
 IF COL_LENGTH(N'dbo.stock_movements',N'warehouse_name') IS NULL ALTER TABLE dbo.stock_movements ADD warehouse_name nvarchar(100) NULL;
 IF EXISTS(SELECT 1 FROM sys.check_constraints WHERE parent_object_id=OBJECT_ID(N'dbo.stock_movements') AND name=N'CK_stock_movements_source_type' AND definition=N'([source_type]=N''stock_count'' OR [source_type]=N''terminal_sync'' OR [source_type]=N''stock_adjustment'' OR [source_type]=N''purchase_invoice'' OR [source_type]=N''sales_invoice'')') BEGIN
 ALTER TABLE dbo.stock_movements DROP CONSTRAINT CK_stock_movements_source_type;
 ALTER TABLE dbo.stock_movements WITH CHECK ADD CONSTRAINT CK_stock_movements_source_type CHECK(source_type IN(N'sales_invoice',N'purchase_invoice',N'stock_adjustment',N'terminal_sync',N'stock_count',N'goods_receipt_batch'));END;
 IF NOT EXISTS(SELECT 1 FROM sys.check_constraints WHERE parent_object_id=OBJECT_ID(N'dbo.stock_movements') AND name=N'CK_stock_movements_source_type' AND is_disabled=0 AND is_not_trusted=0 AND definition=N'([source_type]=N''goods_receipt_batch'' OR [source_type]=N''stock_count'' OR [source_type]=N''terminal_sync'' OR [source_type]=N''stock_adjustment'' OR [source_type]=N''purchase_invoice'' OR [source_type]=N''sales_invoice'')') THROW 51960,'CLEAN_INBOUND_STOCK_SOURCE_SCHEMA',1;`;
const readyCall=`${CLEAN_TARGET_SQL}\nEXEC dbo.usp_clean_store_day_ready;`;
function createNativeSupplier(){const t=fs.readFileSync(new URL('../../infra/sql/migrations/0004_supplier_movements.sql',import.meta.url),'utf8');return t.slice(t.indexOf('\nGO')+3).split(/\bGO\s*\r?\n/)[0];}
export function buildCleanStoreDayDefinitions(){
 const defs={};
 defs.usp_clean_store_day_ready=`CREATE PROCEDURE dbo.usp_clean_store_day_ready WITH EXECUTE AS OWNER AS BEGIN SET NOCOUNT ON;${CLEAN_TARGET_SQL}
 IF ORIGINAL_LOGIN() COLLATE Latin1_General_100_BIN2<>N'${CLEAN_LOGIN}' AND ISNULL(IS_SRVROLEMEMBER(N'sysadmin',ORIGINAL_LOGIN()),0)<>1 ${deny}
 IF (SELECT COUNT(*) FROM dbo.clean_store_day_module_manifest)<>/*ACTIVE_COUNT*/ OR EXISTS(SELECT 1 FROM dbo.clean_store_day_module_manifest e WHERE e.after_hash<>CONVERT(char(64),HASHBYTES('SHA2_256',OBJECT_DEFINITION(OBJECT_ID(N'dbo.'+e.name))),2) OR OBJECT_DEFINITION(OBJECT_ID(N'dbo.'+e.name)) IS NULL OR (OBJECTPROPERTY(OBJECT_ID(N'dbo.'+e.name),'IsTrigger')=1 AND OBJECTPROPERTY(OBJECT_ID(N'dbo.'+e.name),'ExecIsTriggerDisabled')<>0)) THROW 51960,'CLEAN_INBOUND_COHORT_DRIFT',1;
 IF (SELECT COUNT(*) FROM dbo.clean_order_sale_definitions)<>12 OR EXISTS(SELECT 1 FROM dbo.clean_order_sale_definitions d WHERE ${cleanInboundEffectiveDefinitionHashSql()}<>CONVERT(char(64),HASHBYTES('SHA2_256',OBJECT_DEFINITION(OBJECT_ID(N'dbo.'+d.name))),2) OR OBJECT_DEFINITION(OBJECT_ID(N'dbo.'+d.name)) IS NULL OR(OBJECTPROPERTY(OBJECT_ID(N'dbo.'+d.name),'IsTrigger')=1 AND OBJECTPROPERTY(OBJECT_ID(N'dbo.'+d.name),'ExecIsTriggerDisabled')<>0)) THROW 51960,'CLEAN_INBOUND_SALE_HISTORY_DRIFT',1;
 IF (SELECT COUNT(*) FROM dbo.crm_order_v2_definitions)<>8 OR EXISTS(SELECT 1 FROM dbo.crm_order_v2_definitions d WHERE d.definition_hash<>CONVERT(char(64),HASHBYTES('SHA2_256',OBJECT_DEFINITION(OBJECT_ID(N'dbo.'+d.name))),2) OR OBJECT_DEFINITION(OBJECT_ID(N'dbo.'+d.name)) IS NULL OR(OBJECTPROPERTY(OBJECT_ID(N'dbo.'+d.name),'IsTrigger')=1 AND OBJECTPROPERTY(OBJECT_ID(N'dbo.'+d.name),'ExecIsTriggerDisabled')<>0)) THROW 51960,'CLEAN_INBOUND_DRAFT_DRIFT',1;
 IF (SELECT COUNT(*) FROM dbo.clean_order_sale_compatibility)<>2 OR EXISTS(SELECT 1 FROM dbo.clean_order_sale_compatibility d WHERE d.definition_hash<>CONVERT(char(64),HASHBYTES('SHA2_256',OBJECT_DEFINITION(OBJECT_ID(N'dbo.'+d.name))),2) OR OBJECT_DEFINITION(OBJECT_ID(N'dbo.'+d.name)) IS NULL OR(OBJECTPROPERTY(OBJECT_ID(N'dbo.'+d.name),'IsTrigger')=1 AND OBJECTPROPERTY(OBJECT_ID(N'dbo.'+d.name),'ExecIsTriggerDisabled')<>0)) THROW 51960,'CLEAN_INBOUND_COMPATIBILITY_DRIFT',1;
 IF NOT EXISTS(SELECT 1 FROM dbo.clean_store_day_fixture f JOIN dbo.products p ON p.id=f.product_id JOIN dbo.suppliers s ON s.id=f.supplier_id JOIN dbo.test_purchase_warehouses w ON w.id=f.warehouse_id WHERE f.id=1 AND f.product_id=1 AND f.supplier_id=1 AND f.warehouse_id=1 AND f.purchase_price=60 AND f.currency=N'TRY' AND f.operation_date=CONVERT(date,'20261022',112) AND p.stock_code=N'0007 MELISA' AND p.unit=N'ADET' AND p.is_active=1 AND p.is_deleted=0 AND s.supplier_code=N'ORNEK-T01' AND s.currency_code=N'TRY' AND s.is_active=1 AND s.is_deleted=0 AND w.code=N'ORNEK-20261022') THROW 51960,'CLEAN_INBOUND_FIXTURE_DRIFT',1;
 IF EXISTS(SELECT 1 FROM erp_migration.operation_quarantine_holds WHERE(entity=N'product' AND native_id=1)OR(entity=N'supplier' AND native_id=1)) THROW 51960,'CLEAN_INBOUND_QUARANTINE',1;
 END;`;
 defs.usp_clean_order_sale_begin_v3=buildCleanCompatibleSaleBegin().replace('usp_clean_order_sale_begin_v2 ','usp_clean_order_sale_begin_v3 ').replace(cleanOrderSaleReadinessSql(),readyCall).replace('\n IF @@TRANCOUNT=0',`\n IF EXISTS(SELECT 1 FROM dbo.clean_store_day_intents WHERE session_id=@@SPID AND transaction_id=CURRENT_TRANSACTION_ID()) ${deny}\n IF @@TRANCOUNT=0`);
 defs.usp_clean_order_sale_finish_v2=buildCleanOrderSaleProcedures().usp_clean_order_sale_finish.replace('usp_clean_order_sale_finish ','usp_clean_order_sale_finish_v2 ').replace(cleanOrderSaleReadinessSql(),readyCall);
 defs.usp_clean_store_day_bind=`CREATE PROCEDURE dbo.usp_clean_store_day_bind @actor_id bigint,@operation nvarchar(40),@request_id uniqueidentifier,@payload_hash char(64),@payload_json nvarchar(max),@receipt_id bigint=NULL,@invoice_id bigint=NULL WITH EXECUTE AS OWNER AS BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;${readyCall}${original}
 IF @@TRANCOUNT<>1 OR ISNULL(APPLOCK_MODE(N'public',N'CLEAN_STORE_DAY_20261022',N'Transaction'),N'NoLock')<>N'Exclusive' OR EXISTS(SELECT 1 FROM dbo.clean_store_day_intents WHERE session_id=@@SPID) OR EXISTS(SELECT 1 FROM dbo.clean_order_sale_intents WHERE session_id=@@SPID AND transaction_id=CURRENT_TRANSACTION_ID()) ${deny}
 DECLARE @permission nvarchar(80)=CASE @operation WHEN N'count_create' THEN N'goods.create' WHEN N'count_update' THEN N'goods.create' WHEN N'count_submit' THEN N'goods.create' WHEN N'count_cancel' THEN N'goods.create' WHEN N'goods_accept' THEN N'goods.approve' WHEN N'goods_reject' THEN N'goods.reject' WHEN N'purchase_draft' THEN N'purchase.create' WHEN N'purchase_finalize' THEN N'purchase.finalize' END;
 IF @permission IS NULL OR @request_id IS NULL OR @payload_json IS NULL OR ISJSON(@payload_json)<>1 OR @payload_hash IS NULL OR LOWER(CONVERT(char(64),HASHBYTES('SHA2_256',@payload_json),2))<>LOWER(@payload_hash) OR ISNULL(JSON_VALUE(@payload_json,'$.actorId'),N'')<>CONVERT(nvarchar(20),@actor_id) OR ISNULL(JSON_VALUE(@payload_json,'$.operation'),N'')<>@operation OR LOWER(ISNULL(JSON_VALUE(@payload_json,'$.requestId'),N''))<>LOWER(CONVERT(nvarchar(36),@request_id)) ${deny}
 IF NOT EXISTS(SELECT 1 FROM dbo.users u JOIN dbo.roles r ON r.id=u.role_id JOIN dbo.permissions p ON p.role_id=r.id WHERE u.id=@actor_id AND u.is_active=1 AND ((@actor_id=18 AND u.username=N'ornek-depo' AND r.code=N'clean_test_warehouse' AND @operation LIKE N'count[_]%')OR(@actor_id=19 AND u.username=N'ornek-kontrol' AND r.code=N'clean_test_inbound_supervisor' AND @operation NOT LIKE N'count[_]%')) AND p.permission_key=@permission AND(p.can_create=1 OR p.can_approve=1)) ${deny}
 IF EXISTS(SELECT 1 FROM dbo.work_inbound_requests WHERE request_id=@request_id) THROW 51964,'CLEAN_INBOUND_REQUEST_CONFLICT',1;
 DECLARE @count bigint=NULL,@qty decimal(18,3)=NULL,@total decimal(18,4)=0,@receiptBefore nvarchar(20)=NULL,@invoiceBefore nvarchar(20)=NULL,@stock decimal(18,3),@balance decimal(18,4);
 SELECT @stock=current_stock_qty FROM dbo.products WITH(UPDLOCK,HOLDLOCK) WHERE id=1;SELECT @balance=balance FROM dbo.suppliers WITH(UPDLOCK,HOLDLOCK) WHERE id=1;IF @stock IS NULL OR @balance IS NULL ${deny}
 IF @operation LIKE N'count[_]%' BEGIN
 IF @actor_id<>18 OR @receipt_id IS NOT NULL OR @invoice_id IS NOT NULL ${deny}
 IF @operation=N'count_create' BEGIN IF(SELECT COUNT(*) FROM dbo.work_inbound_counts)>=5 THROW 51963,'CLEAN_INBOUND_COUNT_LIMIT',1;END
 ELSE BEGIN SET @count=TRY_CONVERT(bigint,JSON_VALUE(@payload_json,'$.id'));IF NOT EXISTS(SELECT 1 FROM dbo.work_inbound_counts WITH(UPDLOCK,HOLDLOCK) WHERE id=@count AND created_by=18 AND state IN(N'draft',N'needs_review')) THROW 51963,'CLEAN_INBOUND_STALE',1;END;
 IF @operation=N'count_submit' BEGIN SELECT @qty=TRY_CONVERT(decimal(18,3),JSON_VALUE(lines_json,'$[0].physicalQuantityExact3')) FROM dbo.work_inbound_counts WHERE id=@count AND state=N'draft' AND JSON_VALUE(lines_json,'$[0].productId')=N'1' AND(SELECT COUNT(*) FROM OPENJSON(lines_json))=1;IF @qty IS NULL OR @qty NOT BETWEEN 1 AND 5 OR @qty<>FLOOR(@qty) ${deny} END;
 END ELSE IF @operation IN(N'goods_accept',N'goods_reject') BEGIN
 IF @actor_id<>19 OR @invoice_id IS NOT NULL OR @receipt_id IS NULL OR @receipt_id<>TRY_CONVERT(bigint,JSON_VALUE(@payload_json,'$.id')) ${deny}
 SELECT @receiptBefore=state FROM dbo.test_goods_batches WITH(UPDLOCK,HOLDLOCK) WHERE id=@receipt_id AND supplier_id=1 AND warehouse_id=1 AND created_by=18;
 IF @receiptBefore IS NULL OR(@operation=N'goods_accept' AND @receiptBefore=N'rejected')OR(@operation=N'goods_reject' AND @receiptBefore=N'accepted') ${deny}
 SELECT @qty=quantity FROM dbo.test_goods_batch_lines WITH(UPDLOCK,HOLDLOCK) WHERE batch_id=@receipt_id AND product_id=1;IF @qty IS NULL OR(SELECT COUNT(*) FROM dbo.test_goods_batch_lines WHERE batch_id=@receipt_id)<>1 ${deny}
 END ELSE IF @operation=N'purchase_draft' BEGIN
 IF @actor_id<>19 OR @invoice_id IS NOT NULL OR @receipt_id IS NULL OR @receipt_id<>TRY_CONVERT(bigint,JSON_VALUE(@payload_json,'$.batchId')) OR JSON_VALUE(@payload_json,'$.currency')<>N'TRY' OR TRY_CONVERT(date,JSON_VALUE(@payload_json,'$.date'))<>CONVERT(date,'20261022',112) OR JSON_VALUE(@payload_json,'$.number') NOT LIKE N'TSTB-%' OR(SELECT COUNT(*) FROM OPENJSON(@payload_json,'$.lines'))<>1 ${deny}
 SELECT @qty=TRY_CONVERT(decimal(18,3),JSON_VALUE(@payload_json,'$.lines[0].quantity'));
 IF @qty IS NULL OR @qty NOT BETWEEN 1 AND 5 OR @qty<>FLOOR(@qty) OR ISNULL(TRY_CONVERT(decimal(18,4),JSON_VALUE(@payload_json,'$.lines[0].purchasePrice')),-1)<>60 OR ISNULL(TRY_CONVERT(decimal(18,4),JSON_VALUE(@payload_json,'$.lines[0].lineDiscountRate')),-1)<>0 OR ISNULL(TRY_CONVERT(decimal(18,4),JSON_VALUE(@payload_json,'$.invoiceDiscountRate')),-1)<>0 OR ISNULL(TRY_CONVERT(decimal(18,4),JSON_VALUE(@payload_json,'$.vatRate')),-1)<>0 ${deny}
 IF NOT EXISTS(SELECT 1 FROM dbo.test_goods_batches b JOIN dbo.test_goods_batch_lines l ON l.batch_id=b.id WHERE b.id=@receipt_id AND b.state=N'accepted' AND b.supplier_id=1 AND b.warehouse_id=1 AND l.product_id=1 AND l.id=TRY_CONVERT(bigint,JSON_VALUE(@payload_json,'$.lines[0].receiptLineId')) AND @qty<=l.quantity-COALESCE((SELECT SUM(x.quantity) FROM dbo.test_purchase_batch_links x JOIN dbo.purchase_invoices p ON p.id=x.invoice_id WHERE x.receipt_line_id=l.id AND p.status<>N'cancelled'),0)) ${deny}
 IF EXISTS(SELECT 1 FROM dbo.purchase_invoices WHERE supplier_id=1 AND document_no=JSON_VALUE(@payload_json,'$.number')) THROW 51963,'CLEAN_INBOUND_DUPLICATE_INVOICE',1;
 SET @total=@qty*60;
 END ELSE IF @operation=N'purchase_finalize' BEGIN
 IF @actor_id<>19 OR @invoice_id IS NULL OR @invoice_id<>TRY_CONVERT(bigint,JSON_VALUE(@payload_json,'$.id')) OR @receipt_id IS NULL ${deny}
 SELECT @invoiceBefore=status,@total=grand_total FROM dbo.purchase_invoices WITH(UPDLOCK,HOLDLOCK) WHERE id=@invoice_id AND supplier_id=1 AND status IN(N'draft',N'finalized') AND document_currency=N'TRY';
 SELECT @qty=i.quantity FROM dbo.purchase_invoice_items i JOIN dbo.test_purchase_batch_links l ON l.invoice_item_id=i.id AND l.invoice_id=i.purchase_invoice_id JOIN dbo.test_goods_batch_lines g ON g.id=l.receipt_line_id JOIN dbo.test_goods_batches b ON b.id=g.batch_id WHERE i.purchase_invoice_id=@invoice_id AND i.product_id=1 AND b.id=@receipt_id AND b.state=N'accepted' AND b.supplier_id=1 AND i.purchase_price=60 AND i.quantity=l.quantity AND i.quantity<=g.quantity;
 IF @invoiceBefore IS NULL OR @qty IS NULL OR @total<>@qty*60 OR(SELECT COUNT(*) FROM dbo.purchase_invoice_items WHERE purchase_invoice_id=@invoice_id)<>1 ${deny}
 END ELSE ${deny}
 INSERT dbo.clean_store_day_intents(session_id,transaction_id,request_id,actor_id,operation,payload_hash,payload_json,count_id,receipt_id,invoice_id,quantity,total,stock_before,supplier_balance_before,customer_balance_before,stock_count_before,supplier_movement_count_before,receipt_state_before,invoice_state_before)
 SELECT @@SPID,CURRENT_TRANSACTION_ID(),@request_id,@actor_id,@operation,UPPER(@payload_hash),@payload_json,@count,@receipt_id,@invoice_id,@qty,@total,@stock,@balance,c.balance,(SELECT COUNT(*) FROM dbo.stock_movements),(SELECT COUNT(*) FROM dbo.supplier_movements),@receiptBefore,@invoiceBefore FROM dbo.customers c WHERE c.id=1;
 DECLARE @actor bigint=@actor_id,@op nvarchar(40)=@operation,@hash char(64)=@payload_hash;${witness('accepted')} END;`;
 defs.usp_clean_store_day_guard=`CREATE PROCEDURE dbo.usp_clean_store_day_guard @table_name sysname,@inserted nvarchar(max),@deleted nvarchar(max) WITH EXECUTE AS OWNER AS BEGIN SET NOCOUNT ON;${CLEAN_TARGET_SQL}${active}${commonVars}
 IF ISJSON(@inserted)<>1 OR ISJSON(@deleted)<>1 ${deny} DECLARE @ni int=(SELECT COUNT(*) FROM OPENJSON(@inserted)),@nd int=(SELECT COUNT(*) FROM OPENJSON(@deleted));IF @ni<>1 OR @nd>1 ${deny}
 IF @table_name=N'products' BEGIN IF @op<>N'goods_accept' OR @receiptBefore<>N'pending' OR @nd<>1 OR ${N('id')}<>1 OR ISNULL(TRY_CONVERT(decimal(18,3),JSON_VALUE(@deleted,'$[0].current_stock_qty')),-999999)<>@stock OR ${N('current_stock_qty')}<>@stock+@qty ${deny} ${unchanged(['current_stock_qty','updated_at','row_version'])} RETURN;END;
 IF @table_name=N'stock_movements' BEGIN IF @op<>N'goods_accept' OR @receiptBefore<>N'pending' OR @nd<>0 OR ${N('product_id')}<>1 OR ${I('source_type')}<>N'goods_receipt_batch' OR NOT EXISTS(SELECT 1 FROM dbo.test_goods_batch_lines WHERE id=${N('source_id')} AND batch_id=@receipt AND product_id=1) OR ${I('movement_type')}<>N'in' OR ${N('quantity_in')}<>@qty OR ${N('quantity_out')}<>0 OR ${N('quantity_net')}<>@qty OR ${N('unit_cost_try')}<>60 OR ${N('unit_price')}<>60 OR ${N('amount_try')}<>@qty*60 OR ${I('currency_code')}<>N'TRY' OR ${N('supplier_id')}<>1 OR ${N('created_by')}<>19 OR JSON_VALUE(@inserted,'$[0].customer_id') IS NOT NULL OR JSON_VALUE(@inserted,'$[0].average_cost_try_after') IS NOT NULL OR ${I('source_warehouse')}<>N'ORNEK-20261022' OR ${I('warehouse_name')}<>N'Örnek mal kabul deposu' OR TRY_CONVERT(date,${I('document_date')})<>CONVERT(date,'20261022',112) OR(SELECT COUNT(*) FROM dbo.stock_movements WHERE source_type=N'goods_receipt_batch' AND source_id=${N('source_id')})<>1 ${deny} RETURN;END;
 IF @table_name=N'audit_logs' BEGIN IF @nd<>0 OR ${N('actor_user_id')}<>@actor OR NOT((@op IN(N'purchase_draft',N'purchase_finalize') AND ${I('entity_type')}=N'purchase_invoice' AND ${N('entity_id')}=@invoice AND ${I('action')} IN(N'purchase_invoice_draft_created',N'purchase_invoice_finalized'))OR(@op IN(N'count_submit',N'goods_accept',N'goods_reject') AND ${I('entity_type')}=N'test_goods_batch' AND ${N('entity_id')}=@receipt AND ${I('action')} IN(N'test_batch_counted',N'test_batch_approved',N'test_batch_rejected'))) ${deny} RETURN;END;
 IF @table_name=N'work_inbound_counts' BEGIN
 IF @actor<>18 OR @op NOT IN(N'count_create',N'count_update',N'count_submit',N'count_cancel') OR ${N('created_by')}<>18 OR(SELECT COUNT(*) FROM OPENJSON(JSON_VALUE(@inserted,'$[0].lines_json')))<>1 ${deny}
 DECLARE @lines nvarchar(max)=JSON_VALUE(@inserted,'$[0].lines_json');IF ISJSON(@lines)<>1 OR ISNULL(JSON_VALUE(@lines,'$[0].physicalQuantityExact3'),N'') NOT LIKE N'[1-5].000' OR JSON_VALUE(@lines,'$[0].expectedQuantityExact3') IS NOT NULL OR JSON_VALUE(@lines,'$[0].productId') IS NOT NULL AND JSON_VALUE(@lines,'$[0].productId')<>N'1' OR(JSON_VALUE(@lines,'$[0].barcode') IS NOT NULL AND JSON_VALUE(@lines,'$[0].productId')=N'1' AND JSON_VALUE(@lines,'$[0].barcode')<>N'0000000000007') OR(JSON_VALUE(@lines,'$[0].stockCode') IS NOT NULL AND JSON_VALUE(@lines,'$[0].productId')=N'1' AND JSON_VALUE(@lines,'$[0].stockCode')<>N'0007 MELISA') ${deny}
 IF @op=N'count_create' BEGIN IF @nd<>0 OR @count IS NOT NULL OR ${N('version')}<>1 OR ${I('state')}<>CASE WHEN JSON_VALUE(@lines,'$[0].productId') IS NULL THEN N'needs_review' ELSE N'draft' END ${deny} UPDATE dbo.clean_store_day_intents SET count_id=${N('id')} WHERE session_id=@@SPID AND transaction_id=CURRENT_TRANSACTION_ID();END
 ELSE BEGIN IF @nd<>1 OR ${N('id')}<>@count OR ${N('version')}<>TRY_CONVERT(bigint,JSON_VALUE(@deleted,'$[0].version'))+1 OR JSON_VALUE(@deleted,'$[0].state') NOT IN(N'draft',N'needs_review') ${deny}
 IF @op=N'count_submit' AND(${I('state')}<>N'submitted' OR ${N('receipt_id')}<>@receipt OR JSON_VALUE(@lines,'$[0].productId')<>N'1') ${deny}
 IF @op=N'count_cancel' AND ${I('state')}<>N'cancelled' ${deny}
 IF @op=N'count_update' AND ${I('state')}<>CASE WHEN JSON_VALUE(@lines,'$[0].productId') IS NULL THEN N'needs_review' ELSE N'draft' END ${deny} END;RETURN;END;
 IF @table_name=N'test_goods_batches' BEGIN IF ${N('supplier_id')}<>1 OR ${N('warehouse_id')}<>1 OR ${N('created_by')}<>18 ${deny}
 IF @op=N'count_submit' BEGIN IF @nd<>0 OR @receipt IS NOT NULL OR ${I('state')}<>N'pending' ${deny} UPDATE dbo.clean_store_day_intents SET receipt_id=${N('id')} WHERE session_id=@@SPID AND transaction_id=CURRENT_TRANSACTION_ID();END
 ELSE IF @op IN(N'goods_accept',N'goods_reject') BEGIN IF @nd<>1 OR ${N('id')}<>@receipt OR JSON_VALUE(@deleted,'$[0].state')<>N'pending' OR ${N('decided_by')}<>19 OR ${I('state')}<>CASE WHEN @op=N'goods_accept' THEN N'accepted' ELSE N'rejected' END ${deny} ${unchanged(['state','reason','decided_by','decided_at'])} END ELSE ${deny} RETURN;END;
 IF @table_name=N'test_goods_batch_lines' BEGIN IF @op<>N'count_submit' OR @nd<>0 OR ${N('batch_id')}<>@receipt OR ${N('product_id')}<>1 OR ${N('quantity')}<>@qty OR ${I('unit')}<>N'ADET' OR ${N('unit_factor')}<>1 OR(SELECT COUNT(*) FROM dbo.test_goods_batch_lines WHERE batch_id=@receipt)<>1 ${deny} RETURN;END;
 IF @table_name=N'purchase_invoices' BEGIN IF @op NOT IN(N'purchase_draft',N'purchase_finalize') OR ${N('supplier_id')}<>1 OR ${I('document_currency')}<>N'TRY' OR ${I('supplier_currency')}<>N'TRY' OR ${N('exchange_rate_snapshot')}<>1 OR ${N('grand_total')}<>@total OR ${N('subtotal')}<>@total OR ${N('amount_try')}<>@total OR ${N('discount_total')}<>0 OR ${N('line_discount_total')}<>0 OR ${N('stock_cost_effect_try')}<>@total OR ${I('status')}<>CASE WHEN @op=N'purchase_draft' THEN N'draft' ELSE N'finalized' END OR TRY_CONVERT(date,${I('document_date')})<>CONVERT(date,'20261022',112) ${deny}
 IF JSON_VALUE(@inserted,'$[0].account_currency') IS NOT NULL AND(${I('account_currency')}<>N'TRY' OR ${N('account_amount')}<>@total OR ${N('account_exchange_rate_snapshot')}<>1) ${deny}
 IF @op=N'purchase_draft' AND @nd=0 BEGIN IF @invoice IS NOT NULL OR ${I('document_no')}<>JSON_VALUE(@payload,'$.number') ${deny} UPDATE dbo.clean_store_day_intents SET invoice_id=${N('id')} WHERE session_id=@@SPID AND transaction_id=CURRENT_TRANSACTION_ID();END ELSE IF ${N('id')}<>@invoice ${deny} RETURN;END;
 IF @table_name=N'purchase_invoice_items' BEGIN IF @op<>N'purchase_draft' OR @nd<>0 OR ${N('purchase_invoice_id')}<>@invoice OR ${N('product_id')}<>1 OR ${N('quantity')}<>@qty OR ${N('purchase_price')}<>60 OR ${N('line_discount_rate')}<>0 OR ${N('line_total')}<>@total OR ${N('line_total_try')}<>@total OR ${I('currency_code')}<>N'TRY' OR ${I('stock_effect_snapshot')}<>N'goods_receipt_already_posted' OR ${I('stock_code_snapshot')}<>N'0007 MELISA' OR ${I('product_name_snapshot')}<>(SELECT name FROM dbo.products WHERE id=1) OR(SELECT COUNT(*) FROM dbo.purchase_invoice_items WHERE purchase_invoice_id=@invoice)<>1 ${deny} RETURN;END;
 IF @table_name=N'test_purchase_batch_links' BEGIN IF @op<>N'purchase_draft' OR @nd<>0 OR ${N('invoice_id')}<>@invoice OR ${N('quantity')}<>@qty OR NOT EXISTS(SELECT 1 FROM dbo.purchase_invoice_items i JOIN dbo.test_goods_batch_lines g ON g.id=${N('receipt_line_id')} AND g.batch_id=@receipt WHERE i.id=${N('invoice_item_id')} AND i.purchase_invoice_id=@invoice AND i.product_id=g.product_id AND i.quantity=@qty AND g.quantity>=(SELECT SUM(l.quantity) FROM dbo.test_purchase_batch_links l JOIN dbo.purchase_invoices p ON p.id=l.invoice_id WHERE l.receipt_line_id=g.id AND p.status<>N'cancelled')) ${deny} RETURN;END;
 IF @table_name=N'supplier_movements' BEGIN IF @op<>N'purchase_finalize' OR @invoiceBefore<>N'draft' OR ${N('supplier_id')}<>1 OR ${N('purchase_invoice_id')}<>@invoice OR ${I('movement_type')}<>N'purchase_invoice' OR ${N('amount')}<>@total OR ${N('balance_effect')}<>@total OR ${I('currency_code')}<>N'TRY' OR(SELECT COUNT(*) FROM dbo.supplier_movements WHERE purchase_invoice_id=@invoice)<>1 ${deny} IF JSON_VALUE(@inserted,'$[0].account_currency') IS NOT NULL AND(${I('account_currency')}<>N'TRY' OR ${N('account_amount')}<>@total OR ${N('account_exchange_rate_snapshot')}<>1) ${deny} RETURN;END;
 IF @table_name=N'suppliers' BEGIN IF @op<>N'purchase_finalize' OR @invoiceBefore<>N'draft' OR @nd<>1 OR ${N('id')}<>1 OR ISNULL(TRY_CONVERT(decimal(18,4),JSON_VALUE(@deleted,'$[0].balance')),-999999)<>@balance OR ${N('balance')}<>@balance+@total ${deny} ${unchanged(['balance','updated_at','row_version'])} RETURN;END;
 IF @table_name=N'work_inbound_requests' BEGIN IF @nd<>0 OR LOWER(${I('request_id')})<>LOWER(CONVERT(nvarchar(36),(SELECT request_id FROM dbo.clean_store_day_intents WHERE session_id=@@SPID AND transaction_id=CURRENT_TRANSACTION_ID()))) OR ${N('actor_id')}<>@actor OR ${I('operation')}<>@op OR UPPER(${I('payload_hash')})<>@hash OR ${I('payload_json')} COLLATE Latin1_General_100_BIN2<>@payload COLLATE Latin1_General_100_BIN2 OR ISJSON(JSON_VALUE(@inserted,'$[0].response_json'))<>1 ${deny} RETURN;END;
 ${deny} END;`;
 defs.usp_clean_store_received_purchase_proof=`CREATE PROCEDURE dbo.usp_clean_store_received_purchase_proof @request_id uniqueidentifier,@receipt_id bigint,@invoice_id bigint WITH EXECUTE AS OWNER AS BEGIN SET NOCOUNT ON;${CLEAN_TARGET_SQL}${active}${commonVars}
 IF @op<>N'purchase_finalize' OR @receipt_id<>@receipt OR @invoice_id<>@invoice OR @request_id<>(SELECT request_id FROM dbo.clean_store_day_intents WHERE session_id=@@SPID AND transaction_id=CURRENT_TRANSACTION_ID()) ${deny}
 IF NOT EXISTS(SELECT 1 FROM dbo.purchase_invoices p JOIN dbo.purchase_invoice_items i ON i.purchase_invoice_id=p.id JOIN dbo.test_purchase_batch_links l ON l.invoice_item_id=i.id AND l.invoice_id=p.id JOIN dbo.test_goods_batch_lines g ON g.id=l.receipt_line_id JOIN dbo.test_goods_batches b ON b.id=g.batch_id WHERE p.id=@invoice AND p.supplier_id=1 AND p.document_currency=N'TRY' AND p.account_currency=N'TRY' AND p.account_amount=@total AND p.exchange_rate_snapshot=1 AND p.account_exchange_rate_snapshot=1 AND b.id=@receipt AND b.state=N'accepted' AND b.supplier_id=1 AND b.warehouse_id=1 AND g.product_id=1 AND i.product_id=1 AND i.quantity=l.quantity AND i.quantity=@qty AND i.purchase_price=60 AND i.line_total=@total AND i.stock_effect_snapshot=N'goods_receipt_already_posted' AND i.quantity<=g.quantity AND(SELECT COUNT(*) FROM dbo.stock_movements m WHERE m.source_type=N'goods_receipt_batch' AND m.source_id=g.id AND m.product_id=1 AND m.quantity_in=g.quantity AND m.quantity_out=0 AND m.quantity_net=g.quantity AND m.supplier_id=1 AND m.unit_cost_try=60)=1) OR(SELECT COUNT(*) FROM dbo.purchase_invoice_items WHERE purchase_invoice_id=@invoice)<>1 ${deny}
 SELECT CONVERT(bit,1) verified,CONVERT(varchar(36),environment_id) environmentId,LOWER(CONVERT(varchar(36),@request_id)) requestId,@actor actorId,@op operation,LOWER(@hash) payloadHash,@receipt receiptId,@invoice invoiceId,CONVERT(bit,1) stockAlreadyPosted FROM dbo.clean_test_environment WHERE id=1;END;`;
 defs.usp_clean_store_purchase_party_proof=`CREATE PROCEDURE dbo.usp_clean_store_purchase_party_proof @request_id uniqueidentifier,@supplier_id bigint,@items_json nvarchar(max) WITH EXECUTE AS OWNER AS BEGIN SET NOCOUNT ON;${CLEAN_TARGET_SQL}${active}${commonVars}
 IF @op NOT IN(N'purchase_draft',N'purchase_finalize') OR @supplier_id<>1 OR @request_id<>(SELECT request_id FROM dbo.clean_store_day_intents WHERE session_id=@@SPID AND transaction_id=CURRENT_TRANSACTION_ID()) OR ISJSON(@items_json)<>1 OR(SELECT COUNT(*) FROM OPENJSON(@items_json))<>1 OR ISNULL(TRY_CONVERT(bigint,JSON_VALUE(@items_json,'$[0].productId')),-1)<>1 OR ISNULL(TRY_CONVERT(decimal(18,3),JSON_VALUE(@items_json,'$[0].quantity')),-1)<>@qty OR ISNULL(TRY_CONVERT(decimal(18,4),JSON_VALUE(@items_json,'$[0].purchasePrice')),-1)<>60 OR JSON_VALUE(@items_json,'$[0].currency')<>N'TRY' OR NOT EXISTS(SELECT 1 FROM dbo.test_goods_batches b JOIN dbo.test_goods_batch_lines g ON g.batch_id=b.id WHERE b.id=@receipt AND b.state=N'accepted' AND b.supplier_id=1 AND b.warehouse_id=1 AND g.product_id=1 AND g.quantity>=@qty) ${deny} ${witness('verified')} END;`;
 defs.usp_clean_store_day_finish=`CREATE PROCEDURE dbo.usp_clean_store_day_finish @request_id uniqueidentifier WITH EXECUTE AS OWNER AS BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;${CLEAN_TARGET_SQL}${active}${commonVars}
 IF NOT EXISTS(SELECT 1 FROM dbo.clean_store_day_intents WHERE session_id=@@SPID AND transaction_id=CURRENT_TRANSACTION_ID() AND request_id=@request_id) ${deny}
 DECLARE @stockDelta decimal(18,3)=CASE WHEN @op=N'goods_accept' AND @receiptBefore=N'pending' THEN @qty ELSE 0 END,@balanceDelta decimal(18,4)=CASE WHEN @op=N'purchase_finalize' AND @invoiceBefore=N'draft' THEN @total ELSE 0 END;
 IF NOT EXISTS(SELECT 1 FROM dbo.products WHERE id=1 AND current_stock_qty=@stock+@stockDelta) OR NOT EXISTS(SELECT 1 FROM dbo.suppliers WHERE id=1 AND balance=@balance+@balanceDelta) OR NOT EXISTS(SELECT 1 FROM dbo.customers c JOIN dbo.clean_store_day_intents n ON n.session_id=@@SPID AND n.transaction_id=CURRENT_TRANSACTION_ID() WHERE c.id=1 AND c.balance=n.customer_balance_before) ${deny}
 IF(SELECT COUNT(*) FROM dbo.stock_movements)<>(SELECT stock_count_before FROM dbo.clean_store_day_intents WHERE session_id=@@SPID AND transaction_id=CURRENT_TRANSACTION_ID())+CASE WHEN @stockDelta>0 THEN 1 ELSE 0 END OR(SELECT COUNT(*) FROM dbo.supplier_movements)<>(SELECT supplier_movement_count_before FROM dbo.clean_store_day_intents WHERE session_id=@@SPID AND transaction_id=CURRENT_TRANSACTION_ID())+CASE WHEN @balanceDelta>0 THEN 1 ELSE 0 END ${deny}
 IF @op=N'count_submit' AND NOT EXISTS(SELECT 1 FROM dbo.work_inbound_counts c JOIN dbo.test_goods_batches b ON b.id=c.receipt_id JOIN dbo.test_goods_batch_lines g ON g.batch_id=b.id WHERE c.id=@count AND c.state=N'submitted' AND c.receipt_id=@receipt AND b.state=N'pending' AND g.product_id=1 AND g.quantity=@qty) ${deny}
 IF @op IN(N'goods_accept',N'goods_reject') AND NOT EXISTS(SELECT 1 FROM dbo.test_goods_batches WHERE id=@receipt AND state=CASE WHEN @op=N'goods_accept' THEN N'accepted' ELSE N'rejected' END) ${deny}
 IF @op IN(N'purchase_draft',N'purchase_finalize') BEGIN
 IF NOT EXISTS(SELECT 1 FROM dbo.purchase_invoices p JOIN dbo.purchase_invoice_items i ON i.purchase_invoice_id=p.id JOIN dbo.test_purchase_batch_links l ON l.invoice_item_id=i.id AND l.invoice_id=p.id JOIN dbo.test_goods_batch_lines g ON g.id=l.receipt_line_id WHERE p.id=@invoice AND p.supplier_id=1 AND p.status=CASE WHEN @op=N'purchase_draft' THEN N'draft' ELSE N'finalized' END AND p.grand_total=@total AND p.account_currency=N'TRY' AND p.account_amount=@total AND p.account_exchange_rate_snapshot=1 AND p.document_currency=N'TRY' AND p.exchange_rate_snapshot=1 AND g.batch_id=@receipt AND g.product_id=1 AND i.quantity=@qty AND l.quantity=@qty AND i.purchase_price=60 AND i.line_total=@total AND i.stock_effect_snapshot=N'goods_receipt_already_posted') ${deny}
 IF @op=N'purchase_finalize' AND(SELECT COUNT(*) FROM dbo.supplier_movements WHERE supplier_id=1 AND purchase_invoice_id=@invoice AND movement_type=N'purchase_invoice' AND amount=@total AND balance_effect=@total AND account_currency=N'TRY' AND account_amount=@total AND amount_try=@total AND created_by=19)<>1 ${deny} END;
 DECLARE @response nvarchar(max);SELECT @response=response_json FROM dbo.work_inbound_requests WHERE request_id=@request_id AND actor_id=@actor AND operation=@op AND payload_hash=@hash AND payload_json=@payload;
 IF @response IS NULL OR(@op LIKE N'count[_]%' AND ISNULL(TRY_CONVERT(bigint,JSON_VALUE(@response,'$.draft.id')),-1)<>@count) OR(@op LIKE N'goods[_]%' AND ISNULL(TRY_CONVERT(bigint,JSON_VALUE(@response,'$.id')),-1)<>@receipt) OR(@op LIKE N'purchase[_]%' AND ISNULL(TRY_CONVERT(bigint,JSON_VALUE(@response,'$.id')),-1)<>@invoice) ${deny}
 DELETE dbo.clean_store_day_intents WHERE session_id=@@SPID AND transaction_id=CURRENT_TRANSACTION_ID();${witness('verified')} END;`;
 for(const table of ['work_inbound_counts','work_inbound_requests','test_goods_batches','test_goods_batch_lines','purchase_invoices','purchase_invoice_items','test_purchase_batch_links','supplier_movements','suppliers'])defs['clean_inbound_'+table+'_guard']=`CREATE TRIGGER dbo.clean_inbound_${table}_guard ON dbo.${table} WITH EXECUTE AS OWNER AFTER INSERT,UPDATE,DELETE AS BEGIN SET NOCOUNT ON;DECLARE @i nvarchar(max)=(SELECT * FROM inserted FOR JSON PATH,INCLUDE_NULL_VALUES),@d nvarchar(max)=(SELECT * FROM deleted FOR JSON PATH,INCLUDE_NULL_VALUES);EXEC dbo.usp_clean_store_day_guard @table_name=N'${table}',@inserted=@i,@deleted=@d;END;`;
 for(const table of ['clean_store_day_module_manifest','clean_store_day_fixture','test_purchase_warehouses'])defs['clean_inbound_'+table+'_immutable']=`CREATE TRIGGER dbo.clean_inbound_${table}_immutable ON dbo.${table} AFTER INSERT,UPDATE,DELETE AS BEGIN ${deny} END;`;
 const plan=cleanInboundGuardUpgradePlan();
 const total=Object.keys(defs).length+plan.length;for(const name of Object.keys(defs))defs[name]=defs[name].replaceAll('/*ACTIVE_COUNT*/',String(total));
 return {definitions:defs,guards:plan,total};
}
